# 6. BERTH CATEGORY AND KPI CALCULATIONS
# ============================================================

CATEGORY_ORDER = [
    "국제여객터미널",
    "영도크루즈터미널",
    "감만부두",
    "기타"
]

CATEGORY_COLORS = {
    "국제여객터미널": "#1769D2",
    "영도크루즈터미널": "#35A9E8",
    "감만부두": "#F2C94C",
    "기타": "#83C5F4"
}


def classify_berth_group(berth_name):
    """원본 계선장소명을 화면의 4개 운영 분류로 묶습니다.

    분류 우선순위:
    1) 영도 관련 명칭 -> 영도크루즈터미널
    2) 감만 관련 명칭 -> 감만부두
    3) 국제여객/북항 관련 명칭 -> 국제여객터미널
    4) 그 외 -> 기타

    원본 데이터의 실제 명칭이 다르면 이 함수의 키워드만 조정하면 됩니다.
    """
    text = str(berth_name).strip()

    if "영도" in text:
        return "영도크루즈터미널"

    if "감만" in text:
        return "감만부두"

    if any(keyword in text for keyword in ["국제여객", "국제", "북항"]):
        return "국제여객터미널"

    return "기타"


if not cruise_df.empty:
    cruise_df["계선분류"] = cruise_df["계선장소"].apply(classify_berth_group)

    total_arrivals = len(cruise_df)

    if "승객" in cruise_df.columns:
        total_passengers = cruise_df["승객"].sum(min_count=1)
    else:
        total_passengers = None

    arrival_by_category = (
        cruise_df.groupby("계선분류").size()
        .reindex(CATEGORY_ORDER, fill_value=0)
    )

    if "승객" in cruise_df.columns:
        passenger_by_category = (
            cruise_df.groupby("계선분류")["승객"]
            .agg(lambda values: values.sum(min_count=1))
            .reindex(CATEGORY_ORDER)
        )
    else:
        passenger_by_category = pd.Series(
            index=CATEGORY_ORDER,
            dtype="float64"
        )

    passenger_by_category = passenger_by_category.fillna(0)

else:
    total_arrivals = 0
    total_passengers = None
    arrival_by_category = pd.Series(0, index=CATEGORY_ORDER, dtype="int64")
    passenger_by_category = pd.Series(0, index=CATEGORY_ORDER, dtype="float64")


# Category summary table
berth_summary = pd.DataFrame({
    "계선분류": CATEGORY_ORDER,
    "입항건수": arrival_by_category.values,
    "승객수": passenger_by_category.values
})

if total_arrivals > 0:
    berth_summary["입항비중"] = (
        berth_summary["입항건수"] / total_arrivals * 100
    )
else:
    berth_summary["입항비중"] = 0.0

if total_passengers is not None and pd.notna(total_passengers) and total_passengers > 0:
    berth_summary["승객비중"] = (
        berth_summary["승객수"] / total_passengers * 100
    )
else:
    berth_summary["승객비중"] = 0.0


# Analysis period
if not cruise_df.empty:
    period_start_text = cruise_df["입항일시"].min().strftime("%Y.%m.%d")
    period_end_text = cruise_df["입항일시"].max().strftime("%Y.%m.%d")
else:
    period_start_text = "2013.01.01"
    period_end_text = "2026.10.16"


