st.write("")


def render_berth_kpi(card_key, icon_path, title, value, icon_width=96):

    with st.container(key=card_key, border=True):
        if icon_path.is_file():
            icon_base64 = base64.b64encode(
                icon_path.read_bytes()
            ).decode("utf-8")
            icon_html = (
                f'<img class="berth-kpi-icon" '
                f'src="data:image/png;base64,{icon_base64}" '
                f'alt="{title} 아이콘" />'
            )
        else:
            icon_html = ""

        st.markdown(
            f'<div class="berth-kpi-horizontal">'
            f'{icon_html}'
            f'<div class="berth-kpi-text">'
            f'<span class="berth-kpi-label">{title} :</span>'
            f'<span class="berth-kpi-value">{value}</span>'
            f'</div>'
            f'</div>',
            unsafe_allow_html=True
        )


kpi1, kpi2 = st.columns([1, 1], gap="medium")

with kpi1:
    render_berth_kpi(
        "berth-kpi-arrivals",
        ARRIVAL_ICON_IMAGE,
        "총 입항 건수",
        f"{total_arrivals:,} 척",
        96
    )

with kpi2:
    passengers_display = (
        f"{total_passengers:,.0f}명"
        if total_passengers is not None and pd.notna(total_passengers)
        else "데이터 없음"
    )

    render_berth_kpi(
        "berth-kpi-passengers",
        PASSENGER_ICON_IMAGE,
        "총 승객 규모",
        passengers_display,
        96
    )


